WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE(discounts) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 88 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, plan, AVG(tier_value) FILTER (WHERE plan = 'basic') AS basic_avg_tier_value, COUNT(*) FILTER (WHERE currency = 'THB') AS thb_rows FROM flattened GROUP BY 1, 2 HAVING COUNT(*) FILTER (WHERE currency = 'THB') < 1000
